"""Exercise production cancellation with a blocked read and real temporary media files."""
import pathlib,subprocess,sys,tempfile
classes,android,ecj=map(pathlib.Path,sys.argv[1:])
with tempfile.TemporaryDirectory() as temp:
 p=pathlib.Path(temp)
 sources={
 'android/content/Context.java':'package android.content;public class Context{public boolean stopService(Intent i){return true;}}',
 'android/util/Log.java':'package android.util;public class Log{public static int w(String t,String s,Throwable e){e.printStackTrace();return 0;}}',
 'com/sauzask/nicoid/NicoidDownloadCache.java':'package com.sauzask.nicoid;public class NicoidDownloadCache{public static String t="sm123";public static boolean v=true;}',
 'e/e/a/CacheFolders.java':'package e.e.a;import java.io.*;import android.content.Context;class CacheFolders{static Context context=new Context();static String disk;static String root(Context c){return disk;}static void invalidateSummary(Context c){}static String videoId(String name){java.util.regex.Matcher m=java.util.regex.Pattern.compile("^((?:sm|nm|so|ss)[0-9]+)(?:[._].*)?$").matcher(name);return m.matches()?m.group(1):null;}}',
 'e/e/a/CacheFile.java':'package e.e.a;import java.io.*;class CacheFile extends File{CacheFile(String s){super(s);}}',
 'e/e/a/CachePack.java':'package e.e.a;import java.io.*;class CachePack{static void invalidate(File f){}}',
 'e/e/a/CacheControlTest.java':r'''package e.e.a;
import java.io.*;import java.net.*;import java.nio.file.*;import java.util.concurrent.*;
public class CacheControlTest{
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 public static class Request{volatile boolean aborted;public void abort(){aborted=true;}}
 static class Connection extends HttpURLConnection{volatile boolean closed;Connection()throws Exception{super(new URL("http://localhost/"));}public void connect(){}public boolean usingProxy(){return false;}public void disconnect(){closed=true;}}
 static class Blocked extends InputStream{boolean closed;public synchronized int read()throws IOException{while(!closed)try{wait();}catch(InterruptedException ignored){}throw new IOException("closed");}public synchronized void close(){closed=true;notifyAll();}}
 static void file(Path root,String name)throws Exception{Files.write(root.resolve(name),new byte[]{1,2,3});}
 public static void main(String[] args)throws Exception{Path disk=Paths.get(args[0]);CacheFolders.disk=disk.toString();Path media=disk.resolve("nicoid/nicoid_cache");Files.createDirectories(media);for(String name:new String[]{"sm123.json","sm123.thm","sm123.xml","sm123.m3u8","sm123_0001.m4s","sm123.ncache.part","sm999.mp4","sm999.json","notes.txt"})file(media,name);
 Object service=new Object();CacheControl110.started(service);check(CacheControl110.active(service),"started instance active");Blocked stream=new Blocked();Connection connection=new Connection();Request request=new Request();CountDownLatch ready=new CountDownLatch(1),tail=new CountDownLatch(1);Thread worker=new Thread(()->{try{CacheControl110.enter(service);CacheControl110.connection(connection);CacheControl110.request(request);CacheControl110.stream(stream);ready.countDown();stream.read();throw new AssertionError();}catch(IOException expected){CacheControl110.finish();try{tail.await();}catch(InterruptedException stop){try{tail.await();}catch(InterruptedException ignored){}}}});worker.start();check(ready.await(2,TimeUnit.SECONDS),"worker registered");check(CacheControl110.busy(),"live acquisition tracked");CacheControl110.destroyed(service);CacheControl110.await();check(!CacheControl110.busy(),"cancel closes read even when interrupt alone is ignored");check(connection.closed&&request.aborted,"both transport implementations stopped");check(!CacheControl110.busy(),"worker removed only after exit");check(!Files.exists(media.resolve("sm123.m3u8"))&&!Files.exists(media.resolve("sm123_0001.m4s"))&&!Files.exists(media.resolve("sm123.ncache.part")),"cancelled incomplete media removed");check(Files.exists(media.resolve("sm123.json"))&&Files.exists(media.resolve("sm123.xml")),"metadata remains available for retry");check(Files.exists(media.resolve("sm999.mp4")),"unrelated cache preserved");try{CacheControl110.enter(service);throw new AssertionError();}catch(InterruptedIOException expected){checks++;}
 file(media,"sm123_new.m4s");tail.countDown();worker.join(2000);Thread.sleep(30);check(Files.exists(media.resolve("sm123_new.m4s")),"late worker monitor cannot erase a retry after finish");Object next=new Object();CacheControl110.started(next);check(CacheControl110.active(next)&&!CacheControl110.active(service),"stale callbacks stay rejected during a later acquisition");Thread normal=new Thread(()->{try{CacheControl110.enter(next);CacheControl110.finish();}catch(IOException error){throw new AssertionError(error);}});normal.start();normal.join();CacheControl110.destroyed(next);check(Files.exists(media.resolve("sm999.mp4")),"service teardown preserves successfully completed media");check(CacheControl110.delete(null,"sm123"),"delete interrupted item succeeds");check(!Files.exists(media.resolve("sm123.json"))&&!Files.exists(media.resolve("sm123.xml")),"delete includes metadata");check(!CacheControl110.delete(null,"../sm999"),"invalid delete identity rejected");check(CacheControl110.delete(null,null),"delete all succeeds");check(!Files.exists(media.resolve("sm999.mp4"))&&Files.exists(media.resolve("notes.txt")),"delete all removes cache files only");System.out.println("Cache cancellation and deletion: "+checks+" checks passed");}
}'''
 }
 for name,source in sources.items():f=p/name;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(source)
 deps=f'{classes}:{android}'
 subprocess.run(['java','-jar',str(ecj),'-17','-warn:none','-cp',deps,'-d',str(p),*map(str,p.rglob('*.java'))],check=True)
